// TypeScript Version: 4.1

/**
* Clustering algorithm.
*/
type Algorithm = 'lloyd' | 'elkan';

/**
* Distance metric.
*/
type Metric = 'sqeuclidean' | 'correlation' | 'cosine' | 'cityblock';

/**
* Interface describing clustering results.
*/
interface Results {
	/*
	* Number of times the data was clustered with different initial centroids.
	*/
	replicates?: number;

	/*
	* Index of the initial centroids which produced the best result.
	*/
	replicate?: number;

	/*
	* Distance metric.
	*/
	metric?: Metric;

	/*
	* Number of iterations for best results.
	*/
	iterations?: number;

	/*
	* Clustering algorithm.
	*/
	algorithm?: Algorithm;

	/*
	* Sum of squared distances to the closest centroid for all samples.
	*/
	inertia?: number;

	/*
	* Number of clusters.
	*/
	k?: number;

	/*
	* Number of samples.
	*/
	samples?: number;

	/*
	* Number of features.
	*/
	features?: number;
}

/**
* Interface describing options when serializing a results object to a string.
*/
interface ToStringOptions {
	/**
	* Number of digits to display after decimal points. Default: `4`.
	*/
	digits?: number;
}

/**
* Interface describing a results data structure.
*/
declare class ResultsStruct {
	/**
	* Results constructor.
	*
	* @param arg - buffer or data object
	* @param byteOffset - byte offset
	* @param byteLength - maximum byte length
	* @returns results
	*/
	constructor( arg?: ArrayBuffer | Results, byteOffset?: number, byteLength?: number );

	/*
	* Number of times the data was clustered with different initial centroids.
	*/
	replicates: number;

	/*
	* Index of the initial centroids which produced the best result.
	*/
	replicate: number;

	/*
	* Distance metric.
	*/
	metric: Metric;

	/*
	* Number of iterations for best results.
	*/
	iterations: number;

	/*
	* Clustering algorithm.
	*/
	algorithm: Algorithm;

	/*
	* Number of clusters.
	*/
	k: number;

	/*
	* Number of samples.
	*/
	samples: number;

	/*
	* Number of features.
	*/
	features: number;

	/*
	* Sum of squared distances to the closest centroid for all samples.
	*/
	inertia: number;

	/**
	* Clustering method.
	*/
	method: string;

	/**
	* Serializes a results object as a formatted string.
	*
	* @param options - options object
	* @returns serialized results
	*/
	toString( options?: ToStringOptions ): string;

	/**
	* Serializes a results object as a JSON object.
	*
	* @returns serialized object
	*/
	toJSON(): object;

	/**
	* Returns a DataView of a results object.
	*
	* @returns DataView
	*/
	toDataView(): DataView;
}

/**
* Interface defining a results constructor which is both "newable" and "callable".
*/
interface ResultsConstructor {
	/**
	* Results constructor.
	*
	* @param arg - buffer or data object
	* @param byteOffset - byte offset
	* @param byteLength - maximum byte length
	* @returns struct
	*/
	new( arg?: ArrayBuffer | Results, byteOffset?: number, byteLength?: number ): ResultsStruct;

	/**
	* Results constructor.
	*
	* @param arg - buffer or data object
	* @param byteOffset - byte offset
	* @param byteLength - maximum byte length
	* @returns struct
	*/
	( arg?: ArrayBuffer | Results, byteOffset?: number, byteLength?: number ): ResultsStruct;
}

/**
* Returns a new results constructor for creating a k-means clustering results object.
*
* @param dtype - floating-point data type for storing floating-point results
* @returns results constructor
*
* @example
* var Results = resultsFactory( 'float64' );
* // returns <Function>
*
* var r = new Results();
* // returns <Results>
*
* @example
* var Results = resultsFactory( 'float32' );
* // returns <Function>
*
* var r = new Results();
* // returns <Results>
*/
declare function resultsFactory( dtype: 'float64' | 'float32' ): ResultsConstructor;


// EXPORTS //

export = resultsFactory;
